def process(load_data) -> pd.DataFrame:
    # Check unique histologic types
    serous = load_data[load_data['Histologic_type'].str.contains('serous', case=False, na=False)]
    avg_age = serous['Age'].mean()
    return pd.DataFrame({
        'histologic_type_values': [load_data['Histologic_type'].unique().tolist()],
        'serous_count': [len(serous)],
        'avg_age_serous': [round(avg_age, 1)]
    })
